commit 7457caebdf360178503e6b7536efaf70ae8c1351
Author: Nick Hung <nick@andestech.com>
Date:   Fri Jun 26 09:45:37 2026 +0800

    riscv/andes_ae350: add SimControl exit device at 0xe0080000

    The vplat runtime exits via writes to 0xe0080000 (SimControl), but this
    device was absent from the ae350 machine, causing all vplat ELFs to hang
    indefinitely under QEMU.

    Add an inline MemoryRegionOps handler (andesim_ctrl_ops) at that address.
    Write semantics match the vsim SimControl device: value < 256 is a raw exit
    code; the magic values 0x01234567/68/71 exit 0 (pass/finish/skip) and
    0x01234569/70 exit 1 (fail/warn).

    Co-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>
    Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>

diff --git a/hw/riscv/andes_ae350.c b/hw/riscv/andes_ae350.c
index 3ed4134aed..887572dab1 100644
--- a/hw/riscv/andes_ae350.c
+++ b/hw/riscv/andes_ae350.c
@@ -124,6 +124,7 @@ static const struct MemmapEntry {
     [ANDES_AE350_UART3]             = { 0xf1100000,     0x100000 },
     [ANDES_AE350_DTROM]             = { 0xf2000000,     0x100000 },
     [ANDES_AE350_VIRTIO]            = { 0xfe000000,       0x1000 },
+    [ANDES_AE350_SIM_CTRL]          = { 0xe0080000,       0x1000 },
     [ANDES_AE350_UNCACHEABLE_ALIAS] = { 0x100000000, 0x100000000 },
     [ANDES_AE350_DRAM_ALIAS]        = { 0x800000000,  0x80000000 },
     [ANDES_AE350_DRAM_EXT]          = { 0x880000000, 0x380000000 },
@@ -1331,6 +1332,36 @@ static void subport_write(void *opaque, hwaddr addr, uint64_t value,
     }
 }

+/* SimControl write handler. Interprets writes to offset 0:
+ *   value < 256          → raw exit code (used by vplat _exit()).
+ *   0x01234567/68/71     → exit 0  (FINISHED / PASSED / SKIPPED)
+ *   0x01234569/70        → exit 1  (FAILED / WARNING) */
+static void sim_ctrl_write(void *opaque, hwaddr offset,
+                           uint64_t val, unsigned size)
+{
+    (void)opaque; (void)size;
+    if (offset != 0) {
+        return;
+    }
+    int code;
+    if (val < 256) {
+        code = (int)(uint32_t)val;
+    } else if (val == 0x01234567 || val == 0x01234568 || val == 0x01234571) {
+        code = 0;
+    } else if (val == 0x01234569 || val == 0x01234570) {
+        code = 1;
+    } else {
+        return;
+    }
+    exit(code);
+}
+
+static const MemoryRegionOps andesim_ctrl_ops = {
+    .write = sim_ctrl_write,
+    .endianness = DEVICE_LITTLE_ENDIAN,
+    .valid = { .min_access_size = 4, .max_access_size = 4 },
+};
+
 static const MemoryRegionOps subport_ops = {
     .read = subport_read,
     .write = subport_write,
@@ -1435,6 +1466,15 @@ static void andes_ae350_machine_init(MachineState *machine)
     memory_region_add_subregion(system_memory, memmap[ANDES_AE350_NOR].base,
                                 mask_nor);

+    /* SimControl (vplat runtime exit device @ 0xe0080000) */
+    MemoryRegion *sim_ctrl_mr = g_new(MemoryRegion, 1);
+    memory_region_init_io(sim_ctrl_mr, NULL, &andesim_ctrl_ops, NULL,
+                          "riscv.andes.ae350.sim_ctrl",
+                          memmap[ANDES_AE350_SIM_CTRL].size);
+    memory_region_add_subregion(system_memory,
+                                memmap[ANDES_AE350_SIM_CTRL].base,
+                                sim_ctrl_mr);
+
     /* HVM */
     memory_region_init_ram(mask_hvm, NULL, "riscv.andes.ae350.hvm",
                            1 << bs->soc.hvm_size_pow_2, &error_fatal);
